css-m1-l1.code:
/* In styles.css; im head: <link rel="stylesheet" href="styles.css"> */
body { font-family: system-ui, sans-serif; color: #172438; }
.note { color: #2458a6; }
.note.warning { color: #8a4700; }
/* HTML: <p class="note warning">Bitte prüfen.</p> */

css-m1-l2.code:
*, *::before, *::after { box-sizing: border-box; }
.card {
  width: 100%;
  max-width: 36rem;
  padding: 1.25rem;
  border: 1px solid #aab7c9;
  margin-inline: auto;
  overflow-wrap: anywhere;
}
.card p { margin-block: 0 1rem; }

css-m1-l3.code:
:root { --ink: #172438; --paper: #ffffff; --focus: #1955bb; }
body { color: var(--ink); background: var(--paper); font: 1rem/1.6 system-ui, sans-serif; }
p { max-width: 65ch; }
a { text-underline-offset: .2em; }
:focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }
.error { border-inline-start: 4px solid #a6211b; padding-inline-start: 1rem; }

css-m1-l4.code:
.navigation {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .75rem;
}
.navigation a { padding: .75rem; }
.toolbar { display: flex; gap: .5rem; }

css-m1-l5.code:
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr));
  gap: 1rem;
}
.card { min-width: 0; overflow-wrap: anywhere; }
/* Karten bleiben im DOM in ihrer sinnvollen Lesereihenfolge. */

css-m1-l6.code:
img { max-width: 100%; height: auto; }
.layout { display: grid; gap: 1rem; }
@media (min-width: 50rem) {
  .layout { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); }
}
@media (prefers-reduced-motion: reduce) {
  .animated { animation: none; transition: none; }
}
